import React, { useState } from 'react';
import { ThemeProvider, createTheme, CssBaseline, Box, Tabs, Tab, Paper } from '@mui/material';
import UnifiedChatInterface from './components/UnifiedChatInterface';
import UltimateChatGPTInterface from './components/UltimateChatGPTInterface';
import IntegratedAIChat from './components/IntegratedAIChat';
import AnalyticsDashboard from './components/AnalyticsDashboard';
import ApartmentCommunityAnalyzer from './components/ApartmentCommunityAnalyzer';
import ConstructionCompanyInfo from './components/ConstructionCompanyInfo';
import MarketAnalysisEngine from './components/MarketAnalysisEngine';
import DreamVisualizationSystem from './components/DreamVisualizationSystem';
import ResponsiveDesign from './components/ResponsiveDesign';
import AccessibilityEnhancements from './components/AccessibilityEnhancements';
import { MultilingualProvider, LanguageSelector } from './components/MultilingualSupport';
import AuthWrapper from './components/AuthWrapper';

// 테마 생성
const theme = createTheme({
  palette: {
    mode: 'light',
    primary: {
      main: '#667eea',
    },
    secondary: {
      main: '#764ba2',
    },
    background: {
      default: '#f5f7fa',
    },
  },
  typography: {
    fontFamily: '"Pretendard", "Noto Sans KR", -apple-system, BlinkMacSystemFont, system-ui, sans-serif',
    h1: {
      fontWeight: 700,
    },
    h2: {
      fontWeight: 600,
    },
    h3: {
      fontWeight: 600,
    },
    h4: {
      fontWeight: 600,
    },
    h5: {
      fontWeight: 600,
    },
    h6: {
      fontWeight: 600,
    },
  },
  components: {
    MuiButton: {
      styleOverrides: {
        root: {
          borderRadius: 8,
          textTransform: 'none',
          fontWeight: 500,
        },
      },
    },
    MuiCard: {
      styleOverrides: {
        root: {
          borderRadius: 12,
          boxShadow: '0 2px 8px rgba(0,0,0,0.1)',
        },
      },
    },
    MuiPaper: {
      styleOverrides: {
        root: {
          borderRadius: 8,
        },
      },
    },
  },
});

interface TabPanelProps {
  children?: React.ReactNode;
  index: number;
  value: number;
}

function TabPanel(props: TabPanelProps) {
  const { children, value, index, ...other } = props;

  return (
    <div
      role="tabpanel"
      hidden={value !== index}
      id={`simple-tabpanel-${index}`}
      aria-labelledby={`simple-tab-${index}`}
      {...other}
    >
      {value === index && <Box sx={{ height: '100vh' }}>{children}</Box>}
    </div>
  );
}

const App: React.FC = () => {
  const [tabValue, setTabValue] = useState(0);

  const handleTabChange = (event: React.SyntheticEvent, newValue: number) => {
    setTabValue(newValue);
  };

  return (
    <AuthWrapper>
      <MultilingualProvider>
        <ThemeProvider theme={theme}>
          <CssBaseline />
          <ResponsiveDesign>
            <AccessibilityEnhancements>
              <Box sx={{ height: '100vh', display: 'flex', flexDirection: 'column' }}>
                <Paper sx={{ borderRadius: 0, boxShadow: 1 }}>
                  <Tabs
                    value={tabValue}
                    onChange={handleTabChange}
                    aria-label="CORBU AI 인터페이스 탭"
                    sx={{ borderBottom: 1, borderColor: 'divider' }}
                    variant="scrollable"
                    scrollButtons="auto"
                  >
                    <Tab label="🤖 CORBU AI 채팅" />
                    <Tab label="기본 채팅" />
                    <Tab label="통합 AI 채팅" />
                    <Tab label="분석 대시보드" />
                    <Tab label="커뮤니티 분석" />
                    <Tab label="시공사 정보" />
                    <Tab label="시장 분석" />
                    <Tab label="꿈 시각화" />
                  </Tabs>
                </Paper>

                <TabPanel value={tabValue} index={0}>
                  <UnifiedChatInterface />
                </TabPanel>

                <TabPanel value={tabValue} index={1}>
                  <UltimateChatGPTInterface />
                </TabPanel>

                <TabPanel value={tabValue} index={2}>
                  <IntegratedAIChat />
                </TabPanel>

                <TabPanel value={tabValue} index={3}>
                  <AnalyticsDashboard />
                </TabPanel>

                <TabPanel value={tabValue} index={4}>
                  <ApartmentCommunityAnalyzer />
                </TabPanel>

                <TabPanel value={tabValue} index={5}>
                  <ConstructionCompanyInfo />
                </TabPanel>

                <TabPanel value={tabValue} index={6}>
                  <MarketAnalysisEngine />
                </TabPanel>

                <TabPanel value={tabValue} index={7}>
                  <DreamVisualizationSystem />
                </TabPanel>
              </Box>
            </AccessibilityEnhancements>
          </ResponsiveDesign>
        </ThemeProvider>
      </MultilingualProvider>
    </AuthWrapper>
  );
};

export default App;
